for(const card of studyCards){
 const question=questions.find(q=>q.id===card.id);
 card.type=question?(baseCardTypes[question.type]??"简答解答"):"简答解答";
}
for(const [chapterIndex, entries] of expandedCards.entries()){
 const topic=cardChapters[chapterIndex][0];
 for(const [index,[prompt,answer]] of entries.entries()){
  const type=cardTypes[index<5?0:index<8?1:2];
  studyCards.push({id:`ch${chapterIndex+1}-${index+1}`,topic,type,stem:type==="名词解释"?`解释「${prompt}」。`:prompt,answer});
 }
}

