const existingTerms = new Set(studyCards.filter(card => card.type === "名词解释")
    .map(card => card.stem.replace(/[「」“”‘’？！。\s：]/g, "").replace(/^(名词解释|解释|什么是)/, "")));
for (const [topic, entries] of Object.entries(coreTerms)) {
  for (const [index, [term, answer]] of entries.entries()) {
    if (existingTerms.has(term)) continue;
    existingTerms.add(term);
    studyCards.push({id: `term-${topic}-${index + 1}`, topic, type: "名词解释", stem: `解释「${term}」。`, answer});
  }
}

// Match existing concepts before inserting new glossary cards so reviews keep their IDs.
const glossaryCards = new Map(studyCards.filter(card=>card.type==="名词解释").map(card=>[
  card.stem.match(/^解释「(.+)」。$/)?.[1],card
]));
for(const [number,topic,title,answer,page,lastPage,priority,existingId] of importedGlossary){
  let card=existingId?studyCards.find(item=>item.id===existingId):glossaryCards.get(title);
  if(!card){
    card={id:`glossary-${number}`,topic,type:"名词解释",stem:`解释「${title}」。`,answer};
    studyCards.push(card);
    glossaryCards.set(title,card);
  }
  if(answer)card.answer=answer;
  card.glossaryRefs??=[];
  card.glossaryRefs.push({number,page,lastPage});
  if(priority==="重点中的重点"||!card.priority)card.priority=priority;
}

const studyCardsById = new Map(studyCards.map(card=>[card.id,card]));
for(const [edition,section,title,page,ids] of studyReferences){
  for(const id of ids)if(studyCardsById.has(id))studyCardsById.get(id).reference={edition,section,title,page};
}
for(const [id,revision] of Object.entries(studyRevisions)){
  if(studyCardsById.has(id))Object.assign(studyCardsById.get(id),revision);
}

// Definition cards can also be used as closed-book paper questions.
